impl AssetCoordinator {
    pub fn from_dirs(cache_dir: &Path, config_dir: &Path) -> Self {
        let config_file_path = env::var("BAT_CONFIG_PATH")
            .ok()
            .map(PathBuf::from)
            .unwrap_or_else(|| config_dir.join("config"));
        let folder =
            option_env!("BAT_SYSTEM_CONFIG_PREFIX").unwrap_or(DEFAULT_SYSTEM_CONFIG_PREFIX);
        let mut system_config_path = PathBuf::from(folder);
        system_config_path.push("bat");
        system_config_path.push("config");
        AssetCoordinator {
            cache_dir: cache_dir.to_path_buf(),
            config_dir: config_dir.to_path_buf(),
            config_file_path,
            system_config_path,
            interactive_output: atty::is(Stream::Stdout),
            listing_buffer: String::new(),
            syntax_entries: Vec::new(),
            theme_names: Vec::new(),
            pending_inputs: Vec::new(),
            pending_names: Vec::new(),
            syntax_globs: Vec::new(),
            ignored_suffixes: Vec::new(),
            style_value: None,
            env_opt_text: env::var("BAT_OPTS").ok(),
            controller_ok: true,
        }
    }

    pub fn from_project_dirs() -> Self {
        Self::from_dirs(PROJECT_DIRS.cache_dir(), PROJECT_DIRS.config_dir())
    }

    pub fn with_interactive(mut self, interactive_output: bool) -> Self {
        self.interactive_output = interactive_output;
        self
    }

    pub fn cache_dir_display(&self) -> String {
        self.cache_dir.to_string_lossy().into_owned()
    }

    pub fn clear_cached_assets(&self) {
        self.remove_asset_file(self.cache_dir.join("themes.bin"), "theme set cache");
        self.remove_asset_file(self.cache_dir.join("syntaxes.bin"), "syntax set cache");
        self.remove_asset_file(self.cache_dir.join("metadata.yaml"), "metadata file");
    }

    fn remove_asset_file(&self, path: PathBuf, description: &str) {
        print!("Clearing {} ... ", description);
        match fs::remove_file(&path) {
            Err(err) if err.kind() == io::ErrorKind::NotFound => {
                println!("skipped (not present)");
            }
            Err(err) => {
                println!("could not remove the cache file {:?}: {}", &path, err);
            }
            Ok(_) => println!("okay"),
        }
    }

    pub fn assets_from_cache_or_binary(
        &self,
        use_custom_assets: bool,
    ) -> Result<HighlightingAssets> {
        Self::load_assets_from_dir(&self.cache_dir, use_custom_assets)
    }

    fn load_assets_from_dir(
        cache_dir: &Path,
        use_custom_assets: bool,
    ) -> Result<HighlightingAssets> {
        if let Some(metadata) = AssetsMetadata::load_from_folder(cache_dir)? {
            if !metadata.is_compatible_with(crate_version!()) {
                return Err(format!(
                    "The binary caches for the user-customized syntaxes and themes \
             in '{}' are not compatible with this version of bat ({}). To solve this, \
             either rebuild the cache (bat cache --build) or remove \
             the custom syntaxes/themes (bat cache --clear).\n\
             For more information, see:\n\n  \
             https://github.com/sharkdp/bat#adding-new-syntaxes--language-definitions",
                    cache_dir.to_string_lossy(),
                    crate_version!()
                )
                .into());
            }
        }

        let custom_assets = if use_custom_assets {
            HighlightingAssets::from_cache(cache_dir).ok()
        } else {
            None
        };
        Ok(custom_assets.unwrap_or_else(HighlightingAssets::from_binary))
    }

    pub fn config_dir_display(&self) -> String {
        self.config_dir.to_string_lossy().into_owned()
    }

    pub fn themes_install_path(&self) -> PathBuf {
        self.config_dir.join("themes")
    }

    pub fn user_config_file(&self) -> PathBuf {
        self.config_file_path.clone()
    }

    pub fn system_config_file(&self) -> PathBuf {
        self.system_config_path.clone()
    }

    pub fn config_file_exists(&self) -> bool {
        self.config_file_path.is_file()
    }

    pub fn ensure_config_directory(&self) -> Result<()> {
        match self.config_file_path.parent() {
            Some(path) => {
                fs::create_dir_all(path)?;
                Ok(())
            }
            None => Err(format!(
                "Unable to write config file to: {}",
                self.config_file_path.to_string_lossy()
            )
            .into()),
        }
    }

    pub fn write_default_config(&self) -> Result<()> {
        fs::write(&self.config_file_path, DEFAULT_CONFIG_TEMPLATE).map_err(|e| {
            format!(
                "Failed to create config file at '{}': {}",
                self.config_file_path.to_string_lossy(),
                e
            )
            .into()
        })
    }

    pub fn generate_user_config(&self) -> Result<()> {
        if self.config_file_exists() {
            println!(
                "A config file already exists at: {}",
                self.config_file_path.to_string_lossy()
            );

            print!("Overwrite? (y/N): ");
            io::stdout().flush()?;
            let mut decision = String::new();
            io::stdin().read_line(&mut decision)?;

            if !decision.trim().eq_ignore_ascii_case("Y") {
                return Ok(());
            }
        } else {
            self.ensure_config_directory()?;
        }

        self.write_default_config()?;
        println!(
            "Success! Config file written to {}",
            self.config_file_path.to_string_lossy()
        );
        Ok(())
    }

    pub fn parse_config_text(
        content: &str,
    ) -> std::result::Result<Vec<OsString>, shell_words::ParseError> {
        let args_per_line = content
            .split('\n')
            .map(|line| line.trim())
            .filter(|line| !line.is_empty())
            .filter(|line| !line.starts_with('#'))
            .map(shell_words::split)
            .collect::<std::result::Result<Vec<_>, _>>()?;

        Ok(args_per_line
            .iter()
            .flatten()
            .map(|line| line.into())
            .collect())
    }

    pub fn read_combined_config_args(
        &self,
    ) -> std::result::Result<Vec<OsString>, shell_words::ParseError> {
        let mut config = String::new();
        if let Ok(c) = fs::read_to_string(&self.system_config_path) {
            config.push_str(&c);
            config.push('\n');
        }
        if let Ok(c) = fs::read_to_string(&self.config_file_path) {
            config.push_str(&c);
        }
        Self::parse_config_text(&config)
    }

    pub fn env_opts_args(
        &self,
    ) -> Option<std::result::Result<Vec<OsString>, shell_words::ParseError>> {
        self.env_opt_text
            .as_ref()
            .map(|s| Self::parse_config_text(s))
    }

    pub fn env_flag_args() -> Vec<OsString> {
        [
            ("--tabs", "BAT_TABS"),
            ("--theme", "BAT_THEME"),
            ("--pager", "BAT_PAGER"),
            ("--style", "BAT_STYLE"),
        ]
        .iter()
        .filter_map(|(flag, key)| env::var(key).ok().map(|var| [flag.to_string(), var]))
        .flatten()
        .map(|a| a.into())
        .collect()
    }

    pub fn collect_arg_os_strings(&self) -> Result<Vec<OsString>> {
        let args = if wild::args_os().nth(1) == Some("cache".into()) {
            wild::args_os().collect::<Vec<_>>()
        } else if wild::args_os().any(|arg| arg == "--no-config") {
            let mut cli_args = wild::args_os();
            let mut args = Self::env_flag_args();
            args.insert(0, cli_args.next().unwrap());
            cli_args.for_each(|a| args.push(a));
            args
        } else {
            let mut cli_args = wild::args_os();
            let mut args = if let Some(ref opt_text) = self.env_opt_text {
                Self::parse_config_text(opt_text)
            } else {
                self.read_combined_config_args()
            }
            .map_err(|_| "Could not parse configuration file")?;
            args.extend(Self::env_flag_args());
            args.insert(0, cli_args.next().unwrap());
            cli_args.for_each(|a| args.push(a));
            args
        };
        Ok(args)
    }

    fn is_truecolor_terminal() -> bool {
        env::var("COLORTERM")
            .map(|colorterm| colorterm == "truecolor" || colorterm == "24bit")
            .unwrap_or(false)
    }

