pub fn list_themes(&mut self, cfg: &Config) -> Result<()> {
    self.reset_theme_names();
    let assets = Self::load_assets_from_dir(&self.cache_dir, cfg.use_custom_assets)?;
    self.collect_theme_names(&assets);
    if self.theme_names.is_empty() && !cfg.colored_output {
        return Ok(());
    }
    if cfg.colored_output {
        self.print_theme_previews(cfg, &assets)?;
    } else {
        self.print_theme_names_plain()?;
    }
    Ok(())
}

pub fn run_controller(&mut self, inputs: Vec<Input>, config: &Config) -> Result<bool> {
    let assets = Self::load_assets_from_dir(&self.cache_dir, config.use_custom_assets)?;
    let controller = Controller::new(config, &assets);
    self.controller_ok = controller.run(inputs)?;
    Ok(self.controller_ok)
}

#[cfg(feature = "build-assets")]
pub fn build_assets(&self, matches: &ArgMatches) -> Result<()> {
    let source_dir = matches
        .get_one::<String>("source")
        .map(Path::new)
        .unwrap_or_else(|| self.config_dir.as_path());
    let target_dir = matches
        .get_one::<String>("target")
        .map(Path::new)
        .unwrap_or_else(|| self.cache_dir.as_path());

    bat::assets::build(
        source_dir,
        !matches.get_flag("blank"),
        matches.get_flag("acknowledgements"),
        target_dir,
        clap::crate_version!(),
    )
}

